mod solution;

fn main() {
    let cases = [
    (r#"[100,80,60,70,60,75,85]"#, r#"1,1,1,2,1,4,6"#),
    (r#"[10,20,15]"#, r#"1,2,1"#),
    (r#"
[10,20,15]
"#, r#"1,2,1"#),
    (r#"  
[100,80,60,70,60,75,85]
  "#, r#"1,1,1,2,1,4,6"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS monotonic-decreasing-stack");
}
